const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#site-nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.querySelectorAll('.toggle-accordion').forEach((heading,i)=>{const answer=heading.nextElementSibling;if(!answer)return;const text=heading.textContent.trim();heading.innerHTML='';const button=document.createElement('button');button.textContent=text;button.type='button';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','faq-'+i);answer.id='faq-'+i;answer.hidden=true;heading.append(button);button.addEventListener('click',()=>{answer.hidden=!answer.hidden;button.setAttribute('aria-expanded',String(!answer.hidden))})});
const dialog=document.querySelector('#video-dialog');if(dialog){const video=dialog.querySelector('video');document.querySelector('.play-video').addEventListener('click',()=>{dialog.showModal();video.play().catch(()=>{})});dialog.querySelector('.close-video').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>video.pause());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}
document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const body=`Name: ${f.get('name')}\nEmail: ${f.get('email')}\nCollege / university: ${f.get('school')}\nInterest: ${f.get('interest')}\n\n${f.get('message')}`;const subject=`Lifetopia enquiry: ${f.get('interest')}`;location.href='mailto:sales@lifetopia.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent='Your email draft is ready. If your email app did not open, email sales@lifetopia.com directly.'});
